import React, { useState, useEffect } from 'react';
import axios from 'axios';

const Login = ({ setToken }) => {
  const [credentials, setCredentials] = useState({
    username: '',
    password: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setCredentials({
      ...credentials,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await axios.post('http://localhost:5000/api/login', credentials);
      setToken(response.data.access_token);
    } catch (error) {
      setError(error.response?.data?.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <form className="login-form" onSubmit={handleSubmit}>
        <div className="logo-section">
          <div className="logo">FG</div>
          <h2>FinanceGuard Pro</h2>
          <p style={{color: '#6b7280', fontSize: '0.95rem', marginTop: '0.5rem', fontWeight: '500'}}>Enterprise Financial Anomaly Detection</p>
        </div>

        {error && <div className="error">{error}</div>}

        <div className="form-group">
          <label>Username</label>
          <input
            type="text"
            name="username"
            value={credentials.username}
            onChange={handleChange}
            required
            placeholder="Enter your username"
            style={{padding: '0.875rem 1rem', fontSize: '0.95rem'}}
          />
        </div>
        <div className="form-group">
          <label>Password</label>
          <input
            type="password"
            name="password"
            value={credentials.password}
            onChange={handleChange}
            required
            placeholder="Enter your password"
            style={{padding: '0.875rem 1rem', fontSize: '0.95rem'}}
          />
        </div>
        <button 
          type="submit" 
          className="btn" 
          disabled={loading}
          style={{
            width: '100%',
            padding: '1rem',
            fontSize: '1rem',
            fontWeight: '600',
            background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
            border: 'none',
            marginTop: '0.5rem',
            boxShadow: '0 4px 15px rgba(102, 126, 234, 0.4)',
            transition: 'all 0.3s ease',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center'
          }}
        >
          {loading ? 'Signing In...' : 'Sign In'}
        </button>

        <div style={{ 
          marginTop: '1.75rem', 
          fontSize: '0.875rem', 
          color: '#6b7280', 
          textAlign: 'center', 
          padding: '1rem', 
          background: 'linear-gradient(135deg, rgba(102, 126, 234, 0.1), rgba(118, 75, 162, 0.1))', 
          borderRadius: '12px',
          border: '1px solid rgba(102, 126, 234, 0.2)'
        }}>
          <strong style={{color: '#667eea'}}>Default credentials:</strong><br/>
          <span style={{fontFamily: 'monospace', fontSize: '0.9rem'}}>admin / admin123</span>
        </div>
      </form>
    </div>
  );
};

export default Login;
